if($u['role']=='customer'){
 echo '<a class="btn" href="post_job.php"><span class="material-icons mi">add_circle</span> Post New Job</a> <a class="btn" href="match.php"><span class="material-icons mi">gps_fixed</span> Smart Match</a> <a class="btn" href="addresses.php"><span class="material-icons mi">place</span> Addresses</a> <a class="btn" href="leaderboard.php"><span class="material-icons mi">emoji_events</span> Top workers</a><h3><span class="material-icons mi">favorite</span> Favorite Workers</h3><div class="grid">';
 $fv=$pdo->prepare("SELECT u.* FROM favorites f JOIN users u ON u.id=f.worker_id WHERE f.customer_id=?");$fv->execute([$u['id']]);
 foreach($fv as $w)echo '<div class="card"><b>'.e($w['name']).'</b> '.badge($w['verified']).'<br>'.e($w['skill']).'<br><br><a class="btn" href="worker.php?id='.$w['id'].'">View</a></div>';
 echo '</div><h3>My Jobs</h3><div class="grid">';
 $s=$pdo->prepare("SELECT * FROM jobs WHERE customer_id=? ORDER BY id DESC");$s->execute([$u['id']]);jobs($s->fetchAll());echo '</div>';
}elseif($u['role']=='worker'){
 $me=$pdo->prepare("SELECT verified FROM users WHERE id=?");$me->execute([$u['id']]);echo badge($me->fetchColumn());echo ' <a class="btn" href="schedule.php"><span class="material-icons mi">calendar_today</span> My Schedule</a> <a class="btn" href="my_upi.php"><span class="material-icons mi">credit_card</span> '.($u['upi_id']?'My UPI ID':'Add UPI ID <span class="material-icons mi-xs">warning</span>').'</a> <a class="btn" href="upi_confirm.php"><span class="material-icons mi">smartphone</span> UPI confirmations</a> <a class="btn" href="certificates.php"><span class="material-icons mi">school</span> Certificates</a> <a class="btn" href="heatmap.php"><span class="material-icons mi">local_fire_department</span> Demand map</a> <a class="btn" href="leaderboard.php"><span class="material-icons mi-xs">emoji_events</span> Top workers</a> <form method="post" style="display:inline"><button name="alerts" value="1">'.($u['job_alerts']?'<span class="material-icons mi">notifications</span> New-job alerts: ON':'<span class="material-icons mi">notifications_off</span> New-job alerts: OFF').'</button></form>';
 echo '<h3><span class="material-icons mi">lock_open</span> Open Jobs</h3><form method="get" style="display:flex;gap:8px"><input name="q" placeholder="Search title or location" value="'.e($_GET['q']??'').'"><select name="cat"><option value="">All categories</option>';foreach($CATS as $c)echo '<option'.(($_GET['cat']??'')==$c?' selected':'').'>'.$c.'</option>';echo '</select><button>Search</button></form><div class="grid">';
 $k='%'.($_GET['q']??'').'%';$c=$_GET['cat']??'';$s=$pdo->prepare("SELECT * FROM jobs WHERE status='open' AND (title LIKE ? OR location LIKE ?) AND (?='' OR category=?) ORDER BY urgent DESC,(category=?) DESC,id DESC LIMIT 50");$s->execute([$k,$k,$c,$c,$u['skill']]);jobs($s->fetchAll());echo '</div>';
 echo '<p><a class="btn" href="open_jobs.php">See all open jobs →</a></p>';
 echo '<h3>My Assigned Jobs</h3><div class="grid">';
 $s=$pdo->prepare("SELECT * FROM jobs WHERE worker_id=? ORDER BY id DESC");$s->execute([$u['id']]);jobs($s->fetchAll());
 echo '</div>';
}else{
