 echo '<h3><span class="material-icons mi">analytics</span> Analytics</h3><div class="grid"><div class="card"><span class="material-icons mi">people</span> Users<h2>'.$c("SELECT COUNT(*) FROM users").'</h2></div><div class="card"><span class="material-icons mi">engineering</span> Workers<h2>'.$c("SELECT COUNT(*) FROM users WHERE role='worker'").'</h2></div><div class="card"><span class="material-icons mi">assignment</span> Jobs<h2>'.$c("SELECT COUNT(*) FROM jobs").'</h2></div><div class="card"><span class="material-icons mi-xs">check_circle</span> Completed<h2>'.$c("SELECT COUNT(*) FROM jobs WHERE status='completed'").'</h2></div><div class="card"><span class="material-icons mi">payments</span> Income<h2>₹'.(int)$c("SELECT SUM(price) FROM jobs WHERE paid=1").'</h2></div><div class="card"><span class="material-icons mi">account_balance</span> Platform fee (10%)<h2>₹'.(int)$c("SELECT SUM(commission) FROM jobs WHERE paid=1").'</h2></div></div><div class="card"><b>Jobs by category</b>';
 foreach($pdo->query("SELECT category,COUNT(*) n FROM jobs GROUP BY category") as $x)echo '<div>'.e($x['category']).' <span style="display:inline-block;background:#0F62FE;height:12px;width:'.($x['n']*30).'px;max-width:60%"></span> '.$x['n'].'</div>';
 echo '</div><p><a class="btn" href="export.php?t=users"><span class="material-icons mi-xs">arrow_downward</span> Users CSV</a> <a class="btn" href="export.php?t=jobs"><span class="material-icons mi-xs">arrow_downward</span> Jobs CSV</a> <a class="btn" href="export.php?t=payments"><span class="material-icons mi-xs">arrow_downward</span> Payments CSV</a> <a class="btn" href="charts.php"><span class="material-icons mi">trending_up</span> Charts</a> <a class="btn" href="announcements.php"><span class="material-icons mi">campaign</span> Announcements</a> <a class="btn" href="qr_payments.php"><span class="material-icons mi">smartphone</span> QR payments</a> <a class="btn" href="settlements.php"><span class="material-icons mi">attach_money</span> Settlements</a> <a class="btn" href="login_history.php"><span class="material-icons mi">lock</span> Login history</a> <a class="btn" href="my_upi.php"><span class="material-icons mi">credit_card</span> My UPI ID</a> <a class="btn" href="disputes.php"><span class="material-icons mi">balance</span> Disputes</a> <a class="btn" href="certificates.php"><span class="material-icons mi">school</span> Certificates</a> <a class="btn" href="heatmap.php"><span class="material-icons mi">local_fire_department</span> Demand map</a></p><h3>Users</h3><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Skill</th><th>Verified</th><th>Suspend</th></tr>';
 foreach($pdo->query("SELECT * FROM users ORDER BY id DESC") as $x){echo '<tr><td>'.e($x['name']).'</td><td>'.e($x['email']).'</td><td>'.$x['role'].'</td><td>'.e($x['skill']).'</td><td>';
  if($x['role']=='worker')echo '<form method="post"><input type="hidden" name="v" value="'.$x['id'].'"><button>'.($x['verified']?'Remove badge':'Verify').'</button></form>';echo '</td><td>';if($x['role']!='admin')echo '<form method="post"><input type="hidden" name="ban" value="'.$x['id'].'">'.($x['banned']?'<b class="err">Suspended</b> <button>Unban</button>':'<input name="why" placeholder="Reason" required><button style="background:#c00">Ban</button>').'</form>';echo '</td></tr>';}
 echo '</table><h3>All Jobs</h3><div class="grid">';jobs($pdo->query("SELECT * FROM jobs ORDER BY id DESC")->fetchAll());echo '</div>';}
